cells={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
# enumerate 2x2 and L placements
sq=[]; ls=[]
for r in range(4):
 for c in range(6):
  s={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
  if s<=cells: sq.append(s)
  for miss in [(r,c),(r,c+1),(r+1,c),(r+1,c+1)]:
   l={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}-{miss}
   if l<=cells: ls.append(l)
sol=[]
for s in sq:
 rem=cells-s
 def go(left, parts):
  if not left:
   sol.append((s,parts.copy()));return
  x=min(left)
  for l in ls:
   if x in l and l<=left:
    go(left-l,parts+[l])
 go(rem,[])
print('squares',sq,'n solutions',len(sol))
for s,parts in sol:
 print('square',sorted(s),'Ls',[sorted(x) for x in parts])
